// === Tab: mySketch ===
let dots = [];
let nDots = 50;
let dotSize = 30;
let displacement = 30;
let trailLen = 20

// let dotColors = [
//   // CMY
//   [300, 100, 50],
//   [60, 100, 50],
//   [180, 100, 50],
// ];

let dotColors = [
  // 4 colors
  [212, 100, 63],
  [272, 100, 63],
  [32, 100, 63],
  [92, 100, 63],
  [336, 100, 63],
  [36, 100, 63],
  [156, 100, 63],
  [216, 100, 63],
];

let noiseDiff = 1000;
let x, y;
// let bgColor = [120, 100, 50];
let bgColor = [0, 0, 90];

async function setup() {
  frameRate(5);
  createCanvas(1080, 1080);
  colorMode(HSL);
  background(bgColor);
  // x = width / 2;
  // y = height / 2;
  for (let i = 0; i < nDots; i++) {
    dots.push(
      new dotRandomWalker(
        round(random(width) / displacement) * displacement,
        round(random(height) / displacement) * displacement,
        dotSize,
        displacement,
        random(dotColors),
        i * noiseDiff,
        trailLen
      )
    );
  }
}

function draw() {
  background(bgColor);
  noStroke();
  dots.forEach((dot) => dot.draw(frameCount));
}

function mouseClicked() {
  dots.forEach((dot) => dot.resetPos());
}

class dotRandomWalker {
  constructor(x, y, dotSize, displacement, dotColor, noiseDiff, trailLen) {
    this.x = x;
    this.y = y;
    this.origX = x;
    this.origY = y;

    this.dotSize = dotSize;
    this.displacement = displacement;
    this.dotColor = dotColor;
    this.rangeNoise = 1;
    this.noiseScale = 0.01;
    this.trailLen = trailLen; // dots left behind
    this.trail = new Trail(
      this.trailLen,
      x,
      y,
      dotColor,
      -(1/this.trailLen),
      dotSize,
      -(1/this.trailLen)
    );
    this.noiseDiff = noiseDiff;
  }

  draw(frameCount) {
    let nX =
      1 +
      map(
        noise((frameCount + this.noiseDiff) * this.noiseScale),
        0,
        1,
        -this.rangeNoise,
        +this.rangeNoise
      );
    let frameColor = [
      this.dotColor[0],
      this.dotColor[1],
      this.dotColor[2] * nX,
    ];
    this.trail.draw();
    this.x += random([-this.displacement, 0, this.displacement]);
    this.y += random([-this.displacement, 0, this.displacement]);
    this.x = this.wrapPos(this.x, width);
    this.y = this.wrapPos(this.y, height);

    fill(frameColor);
    circle(this.x, this.y, this.dotSize);
    this.trail.update(this.x, this.y);
  }

  resetPos() {
    this.x = this.origX;
    this.y = this.origY;
  }

  wrapPos(pos, maxPos) { // 
    if (pos > maxPos) {
      pos = pos - maxPos;
    }
    if (pos < 0) {
      pos = pos + maxPos;
    }
    return pos
  }
}

class Trail {
  constructor(trailLen, x, y, dotColor, colorChg, dotSize, sizeChg) {
    // dotColor must be an HSL array
    this.trailLen = trailLen;
    this.trailPos = [];
    this.trailColors = [];
    this.colorChg = colorChg; // e.g: -0.05 to reduce 5%
    this.trailSizes = [];
    this.sizeChg = sizeChg; // e.g: -0.05 to reduce 5%
    for (let i = 0; i < this.trailLen; i++) {
      this.trailPos.push([x, y]);
      this.trailColors.push([
        dotColor[0],
        dotColor[1],
        dotColor[2] * (1 + this.colorChg * (i + 1)),
      ]);
      this.trailSizes.push([dotSize * (1 + this.sizeChg * (i + 1))]);
    }
  }

  update(x, y) {
    this.trailPos.pop();
    this.trailPos.unshift([x, y]);
  }

  draw() {
    noStroke();
    for (let i = this.trailLen - 1; i >= 0; i--) {
      fill(this.trailColors[i]);
      circle(this.trailPos[i][0], this.trailPos[i][1], this.trailSizes[i]);
    }
  }
}

